-- translate() was way too slow on big html pages, one regex does the same in one pass
CREATE OR REPLACE FUNCTION job_normalized_text(value text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
    SELECT btrim(regexp_replace(
        regexp_replace(normalize(casefold(value COLLATE "pg_unicode_fast"), NFKD), '[̴̵̶̷̸᳔᳢᳣᳤᳥᳦᳧᳨⃒⃓⃘⃙⃚⃥⃦⃪⃫𐨹𖫰𖫱𖫲𖫳𖫴𛲞𝅧𝅨𝅩𖿰𖿱़়਼઼଼఼಼့᬴᯦᰷꦳𑂺𑅳𑇊𑈶𑋩𑌻𑌼𑑆𑓃𑗀𑚷𑠺𑥃𑵂𞥊゙゚्্੍્୍்్್഻഼്්ฺ຺྄္်᜔᜕᜴្᩠᭄᮪᮫᯲᯳⵿꠆꠬꣄꥓꧀꫶꯭𐨿𑁆𑁰𑁿𑂹𑄳𑄴𑇀𑈵𑋪𑍍𑏎𑏏𑏐𑑂𑓂𑖿𑘿𑚶𑜫𑠹𑤽𑤾𑧠𑨴𑩇𑪙𑰿𑵄𑵅𑶗𑽁𑽂𖄯ְֱֲֳִֵֶַָׇֹֺֻּֽֿׁׂﬞًࣰٌࣱٍࣲؘَؙُؚِّْٰܑౕౖุู่้๊๋ຸູ່້໊໋ཱིེཻོཽྀུ̡̢̧̨᷐᷎̛༹𝅥𝅦𝅮𝅯𝅰𝅱𝅲᷺〪̖̗̘̙̜̝̞̟̠̣̤̥̦̩̪̫̬̭̮̯̰̱̲̳̹̺̻̼͇͈͉͍͎͓͔͕͖͙͚֑֖֛֢֣֤֥֦֧֪ׅٕٖٜٟۣ۪ۭܱܴܷܸܹܻܼܾ݂݄݆݈߲߽࡙࡚࡛࢙࢚࢛࣏࣐࣑࣒࣓ࣣࣦࣩ࣭࣮࣯ࣶࣹࣺ॒༘༙༵༷࿆ႍ᤻ᨘ᩿᪵᪶᪷᪸᪹᪺᪽ᪿᫀ᫃᫄᫊᭬᳕᳖᳗᳘᳙᳜᳝᳞᳟᳭᷂᷊᷏᷹᷽᷿⃨⃬⃭⃮⃯꤫꤬꤭ꪴ︧︨︩︪︫︬︭𐇽𐋠𐨍𐨺𐫦𐻽𐻾𐻿𐽆𐽇𐽋𐽍𐽎𐽏𐽐𐾃𐾅𝅻𝅼𝅽𝅾𝅿𝆀𝆁𝆂𝆊𝆋𞓮𞗯𞣐𞣑𞣒𞣓𞣔𞣕𞣖֚֭᤹〭〮〯𝅭֮ᢩ᷷᷸〫̀́̂̃̄̅̆̇̈̉̊̋̌̍̎̏̐̑̒̓̔̽̾̿̀́͂̓̈́͆͊͋͌͐͑͒͗͛ͣͤͥͦͧͨͩͪͫͬͭͮͯ҃҄҅҆҇֒֓֔֕֗֘֙֜֝֞֟֠֡֨֩֫֬֯ׄؐؑؒؓؔؕؖؗٓٔٗ٘ٙٚٛٝٞۖۗۘۙۚۛۜ۟۠ۡۢۤۧۨ۫۬ܰܲܳܵܶܺܽܿ݀݁݃݅݇݉݊߫߬߭߮߯߰߱߳ࠖࠗ࠘࠙ࠛࠜࠝࠞࠟࠠࠡࠢࠣࠥࠦࠧࠩࠪࠫࠬ࠭ࢗ࢘࢜࢝࢞࢟࣊࣋࣌࣍࣎ࣔࣕࣖࣗࣘࣙࣚࣛࣜࣝࣞࣟ࣠࣡ࣤࣥࣧࣨ࣪࣫࣬ࣳࣴࣵࣷࣸࣻࣼࣽࣾࣿ॑॓॔৾ྂྃ྆྇፝፞፟៝᤺ᨗ᩵᩶᩷᩸᩹᩺᩻᩼᪰᪱᪲᪳᪴᪻᪼᫁᫂᫅᫆᫇᫈᫉᫋ᫌᫍᫎ᭫᭭᭮᭯᭰᭱᭲᭳᳐᳑᳒᳚᳛᳠᳴᳸᳹᷀᷁᷃᷄᷅᷆᷇᷈᷉᷋᷌᷑᷒ᷓᷔᷕᷖᷗᷘᷙᷚᷛᷜᷝᷞᷟᷠᷡᷢᷣᷤᷥᷦᷧᷨᷩᷪᷫᷬᷭᷮᷯᷰᷱᷲᷳᷴ᷵᷻᷾⃐⃑⃔⃕⃖⃗⃛⃜⃡⃧⃩⃰⳯⳰⳱ⷠⷡⷢⷣⷤⷥⷦⷧⷨⷩⷪⷫⷬⷭⷮⷯⷰⷱⷲⷳⷴⷵⷶⷷⷸⷹⷺⷻⷼⷽⷾⷿ꙯ꙴꙵꙶꙷꙸꙹꙺꙻ꙼꙽ꚞꚟ꛰꛱꣠꣡꣢꣣꣤꣥꣦꣧꣨꣩꣪꣫꣬꣭꣮꣯꣰꣱ꪰꪲꪳꪷꪸꪾ꪿꫁︠︡︢︣︤︥︦︮︯𐍶𐍷𐍸𐍹𐍺𐨏𐨸𐫥𐴤𐴥𐴦𐴧𐵩𐵪𐵫𐵬𐵭𐺫𐺬𐽈𐽉𐽊𐽌𐾂𐾄𑄀𑄁𑄂𑍦𑍧𑍨𑍩𑍪𑍫𑍬𑍰𑍱𑍲𑍳𑍴𑑞𖬰𖬱𖬲𖬳𖬴𖬵𖬶𝆅𝆆𝆇𝆈𝆉𝆪𝆫𝆬𝆭𝉂𝉃𝉄𞀀𞀁𞀂𞀃𞀄𞀅𞀆𞀈𞀉𞀊𞀋𞀌𞀍𞀎𞀏𞀐𞀑𞀒𞀓𞀔𞀕𞀖𞀗𞀘𞀛𞀜𞀝𞀞𞀟𞀠𞀡𞀣𞀤𞀦𞀧𞀨𞀩𞀪𞂏𞄰𞄱𞄲𞄳𞄴𞄵𞄶𞊮𞋬𞋭𞋮𞋯𞓯𞗮𞥄𞥅𞥆𞥇𞥈𞥉̕̚͘᷶〬𞓬𞓭͜͟͢᷼͝͞͠͡᷍ͅ]', '', 'g'),
        '[^\w]+', ' ', 'g'))
$fn$;
